-- Canonical private draft taxonomy. Wording comes from owner source; tags are not credentials.
CREATE FUNCTION hashtags_synonyms_valid(v jsonb) RETURNS boolean LANGUAGE sql IMMUTABLE AS $$
 SELECT coalesce(jsonb_typeof(v)='array' AND jsonb_array_length(v) BETWEEN 1 AND 20 AND octet_length(v::text)<=10000 AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(v) e WHERE jsonb_typeof(e)<>'object' OR (e-'term')<>'{}'::jsonb OR jsonb_typeof(e->'term') IS DISTINCT FROM 'string' OR length(btrim(e->>'term')) NOT BETWEEN 1 AND 300),false)
$$;
--> statement-breakpoint
CREATE TABLE hashtags_db (
 id uuid PRIMARY KEY,
 parent_category text NOT NULL,
 sub_category text NOT NULL,
 tag_value text NOT NULL UNIQUE,
 display_label text NOT NULL,
 synonyms_json jsonb NOT NULL,
 weight_score integer NOT NULL DEFAULT 5,
 is_active boolean NOT NULL DEFAULT true,
 source_sha256 text NOT NULL DEFAULT 'f5211313189e3d3074a761868693796e93bb160c01d87f3d2989bac48b2ab75e',
 CONSTRAINT hashtags_db_value CHECK (length(tag_value) BETWEEN 1 AND 100 AND length(display_label) BETWEEN 1 AND 101 AND length(parent_category) BETWEEN 1 AND 200 AND length(sub_category) BETWEEN 1 AND 200),
 CONSTRAINT hashtags_db_synonyms CHECK (hashtags_synonyms_valid(synonyms_json)),
 CONSTRAINT hashtags_db_weight CHECK (weight_score BETWEEN 1 AND 10),
 CONSTRAINT hashtags_db_source CHECK (source_sha256 ~ '^[0-9a-f]{64}$')
);
--> statement-breakpoint
ON CONFLICT(tag_value) DO NOTHING;
--> statement-breakpoint
CREATE VIEW hashtags_taxonomy AS SELECT id,parent_category AS category,display_label AS tag_name,synonyms_json::text AS description_context FROM hashtags_db;
--> statement-breakpoint
ALTER TABLE expert_card_drafts ADD COLUMN input_mode text NOT NULL DEFAULT 'INTERVIEW', ADD COLUMN document_proposal jsonb, ADD COLUMN document_import_revision integer;
ALTER TABLE expert_card_drafts ADD CONSTRAINT expert_card_input_mode CHECK (coalesce((document_import_revision IS NULL OR document_import_revision BETWEEN 1 AND revision) AND input_mode IN ('INTERVIEW','DOCUMENT_PROPOSAL') AND ((input_mode='INTERVIEW' AND document_proposal IS NULL) OR (input_mode='DOCUMENT_PROPOSAL' AND jsonb_typeof(document_proposal)='object' AND jsonb_typeof(document_proposal->'source')='string' AND jsonb_typeof(document_proposal->'content')='string' AND document_proposal ?& ARRAY['source','content'] AND (document_proposal-'source'-'content')='{}'::jsonb AND document_proposal->>'source' IN ('pdf','docx') AND length(btrim(document_proposal->>'content'))>=50 AND octet_length(document_proposal::text)<=100000)),false));
--> statement-breakpoint
CREATE TABLE expert_card_draft_tags (
 draft_id uuid NOT NULL,
 user_id uuid NOT NULL,
 tag_id uuid NOT NULL REFERENCES hashtags_db(id),
 PRIMARY KEY(draft_id,tag_id),
 CONSTRAINT expert_card_draft_tag_owner FOREIGN KEY(draft_id,user_id) REFERENCES expert_card_drafts(id,user_id) ON DELETE CASCADE
);
--> statement-breakpoint
CREATE FUNCTION expert_card_tag_selection_guard() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
 PERFORM 1 FROM expert_card_drafts WHERE id=NEW.draft_id AND user_id=NEW.user_id AND status IN ('collecting','changes_requested') FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'card_tag_draft_unavailable'; END IF;
 PERFORM 1 FROM hashtags_db WHERE id=NEW.tag_id AND is_active FOR SHARE;
 IF NOT FOUND OR (SELECT count(*) FROM expert_card_draft_tags WHERE draft_id=NEW.draft_id)>=20 THEN RAISE EXCEPTION 'card_tag_selection_invalid'; END IF;
 RETURN NEW;
END $$;
--> statement-breakpoint
CREATE TRIGGER expert_card_tag_selection_guard BEFORE INSERT OR UPDATE ON expert_card_draft_tags FOR EACH ROW EXECUTE FUNCTION expert_card_tag_selection_guard();
