-- Informational only: every operation rechecks original consent and current owner.
CREATE VIEW resident_workspace_access AS SELECT a.user_id,a.id AS application_id, true AS has_access_to_work_bot, 'interview'::text AS access_kind FROM expert_onboarding_applications a JOIN users u ON u.id=a.user_id AND u.active WHERE a.verification_status='approved' AND a.onboarding_stage IS NOT NULL AND a.archived_at IS NULL AND EXISTS(SELECT 1 FROM consent_states s JOIN consents c ON c.id=s.last_decision_id WHERE s.user_id=a.user_id AND s.purpose='client_messaging' AND expert_card_current_messaging_authority(a.user_id,c.policy_version)) AND EXISTS(SELECT 1 FROM expert_onboarding_invoices i JOIN expert_onboarding_payment_facts f ON f.invoice_id=i.id AND f.user_id=a.user_id AND f.admission='interview' WHERE i.application_id=a.id AND i.user_id=a.user_id AND i.status='settled');
